// NULL-tolerant scan buffer for characterScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type characterPreloadBuf struct {
	ID               null.Val[int64]
	Name             null.Val[string]
	STR              null.Val[int64]
	Dex              null.Val[int64]
	Con              null.Val[int64]
	Int              null.Val[int64]
	Wis              null.Val[int64]
	Cha              null.Val[int64]
	HPMax            null.Val[int64]
	Thac0Base        null.Val[int64]
	Level            null.Val[int64]
	XPTotal          null.Val[int64]
	SaveParaPoison   null.Val[int64]
	SaveRodStaffWand null.Val[int64]
	SavePetriPoly    null.Val[int64]
	SaveBreath       null.Val[int64]
	SaveSpell        null.Val[int64]
}

// characterScanMapperNullable maps the preloaded character
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func characterScanMapperNullable(prefix string) scan.Mapper[*Character] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Character, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *characterPreloadBuf) any
		}
		targets := make([]target, 0, 17)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.ID }})
			case "name":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Name }})
			case "str":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.STR }})
			case "dex":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Dex }})
			case "con":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Con }})
			case "int":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Int }})
			case "wis":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Wis }})
			case "cha":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Cha }})
			case "hp_max":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.HPMax }})
			case "thac0_base":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Thac0Base }})
			case "level":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.Level }})
			case "xp_total":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.XPTotal }})
			case "save_para_poison":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.SaveParaPoison }})
			case "save_rod_staff_wand":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.SaveRodStaffWand }})
			case "save_petri_poly":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.SavePetriPoly }})
			case "save_breath":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.SaveBreath }})
			case "save_spell":
				targets = append(targets, target{i, func(b *characterPreloadBuf) any { return &b.SaveSpell }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(characterPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Character, error) {
				buf := link.(*characterPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !buf.ID.IsValue() &&
					!buf.Name.IsValue() &&
					!buf.STR.IsValue() &&
					!buf.Dex.IsValue() &&
					!buf.Con.IsValue() &&
					!buf.Int.IsValue() &&
					!buf.Wis.IsValue() &&
					!buf.Cha.IsValue() &&
					!buf.HPMax.IsValue() &&
					!buf.Thac0Base.IsValue() &&
					!buf.Level.IsValue() &&
					!buf.XPTotal.IsValue() &&
					!buf.SaveParaPoison.IsValue() &&
					!buf.SaveRodStaffWand.IsValue() &&
					!buf.SavePetriPoly.IsValue() &&
					!buf.SaveBreath.IsValue() &&
					!buf.SaveSpell.IsValue() {
					return nil, nil
				}

				o := new(Character)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.STR.IsValue() {
					o.STR = buf.STR.MustGet()
				}
				if buf.Dex.IsValue() {
					o.Dex = buf.Dex.MustGet()
				}
				if buf.Con.IsValue() {
					o.Con = buf.Con.MustGet()
				}
				if buf.Int.IsValue() {
					o.Int = buf.Int.MustGet()
				}
				if buf.Wis.IsValue() {
					o.Wis = buf.Wis.MustGet()
				}
				if buf.Cha.IsValue() {
					o.Cha = buf.Cha.MustGet()
				}
				if buf.HPMax.IsValue() {
					o.HPMax = buf.HPMax.MustGet()
				}
				if buf.Thac0Base.IsValue() {
					o.Thac0Base = buf.Thac0Base.MustGet()
				}
				if buf.Level.IsValue() {
					o.Level = buf.Level.MustGet()
				}
				if buf.XPTotal.IsValue() {
					o.XPTotal = buf.XPTotal.MustGet()
				}
				if buf.SaveParaPoison.IsValue() {
					o.SaveParaPoison = buf.SaveParaPoison.MustGet()
				}
				if buf.SaveRodStaffWand.IsValue() {
					o.SaveRodStaffWand = buf.SaveRodStaffWand.MustGet()
				}
				if buf.SavePetriPoly.IsValue() {
					o.SavePetriPoly = buf.SavePetriPoly.MustGet()
				}
				if buf.SaveBreath.IsValue() {
					o.SaveBreath = buf.SaveBreath.MustGet()
				}
				if buf.SaveSpell.IsValue() {
					o.SaveSpell = buf.SaveSpell.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Character) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "ActiveBuffs":
		rels, ok := retrieved.(ActiveBuffSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.ActiveBuffs = rels
		o.R.Loaded.ActiveBuffs = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
				rel.R.Loaded.Character = true
			}
		}
		return nil
	case "HPEvents":
		rels, ok := retrieved.(HPEventSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.HPEvents = rels
		o.R.Loaded.HPEvents = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
				rel.R.Loaded.Character = true
			}
		}
		return nil
	case "RoundStates":
		rels, ok := retrieved.(RoundStateSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.RoundStates = rels
		o.R.Loaded.RoundStates = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
				rel.R.Loaded.Character = true
			}
		}
		return nil
	case "SpellSlots":
		rels, ok := retrieved.(SpellSlotSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.SpellSlots = rels
		o.R.Loaded.SpellSlots = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
				rel.R.Loaded.Character = true
			}
		}
		return nil
	case "XPEvents":
		rels, ok := retrieved.(XPEventSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.XPEvents = rels
		o.R.Loaded.XPEvents = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
				rel.R.Loaded.Character = true
			}
		}
		return nil
	default:
		return fmt.Errorf("character has no relationship %q", name)
	}
}

type characterPreloader struct{}

func buildCharacterPreloader() characterPreloader {
	return characterPreloader{}
}

type characterThenLoader[Q orm.Loadable] struct {
	ActiveBuffs func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	HPEvents    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	RoundStates func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	SpellSlots  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	XPEvents    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildCharacterThenLoader[Q orm.Loadable]() characterThenLoader[Q] {
	type ActiveBuffsLoadInterface interface {
		LoadActiveBuffs(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type HPEventsLoadInterface interface {
		LoadHPEvents(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RoundStatesLoadInterface interface {
		LoadRoundStates(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type SpellSlotsLoadInterface interface {
		LoadSpellSlots(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type XPEventsLoadInterface interface {
		LoadXPEvents(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return characterThenLoader[Q]{
		ActiveBuffs: thenLoadBuilder[Q](
			"ActiveBuffs",
			func(ctx context.Context, exec bob.Executor, retrieved ActiveBuffsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadActiveBuffs(ctx, exec, mods...)
			},
		),
		HPEvents: thenLoadBuilder[Q](
			"HPEvents",
			func(ctx context.Context, exec bob.Executor, retrieved HPEventsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadHPEvents(ctx, exec, mods...)
			},
		),
		RoundStates: thenLoadBuilder[Q](
			"RoundStates",
			func(ctx context.Context, exec bob.Executor, retrieved RoundStatesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadRoundStates(ctx, exec, mods...)
			},
		),
		SpellSlots: thenLoadBuilder[Q](
			"SpellSlots",
			func(ctx context.Context, exec bob.Executor, retrieved SpellSlotsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadSpellSlots(ctx, exec, mods...)
			},
		),
		XPEvents: thenLoadBuilder[Q](
			"XPEvents",
			func(ctx context.Context, exec bob.Executor, retrieved XPEventsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadXPEvents(ctx, exec, mods...)
			},
		),
	}
}

// LoadActiveBuffs loads the character's ActiveBuffs into the .R struct
func (o *Character) LoadActiveBuffs(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.ActiveBuffs = nil
	o.R.Loaded.ActiveBuffs = false

	related, err := o.ActiveBuffs(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Character = o
		rel.R.Loaded.Character = true
	}

	o.R.ActiveBuffs = related
	o.R.Loaded.ActiveBuffs = true
	return nil
}

// LoadActiveBuffs loads the character's ActiveBuffs into the .R struct
func (os CharacterSlice) LoadActiveBuffs(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	activeBuffs, err := os.ActiveBuffs(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ActiveBuffs = nil
		o.R.Loaded.ActiveBuffs = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	characterByKey := make(map[int64][]*Character, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		characterByKey[o.ID] = append(characterByKey[o.ID], o)
	}

	for _, rel := range activeBuffs {

		owners, ok := characterByKey[rel.CharacterID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Character = o
			rel.R.Loaded.Character = true

			o.R.ActiveBuffs = append(o.R.ActiveBuffs, rel)

		}
	}

	return nil
}

