type characterJoins[Q dialect.Joinable] struct {
	typ         string
	ActiveBuffs modAs[Q, activeBuffColumns]
	HPEvents    modAs[Q, hpEventColumns]
	RoundStates modAs[Q, roundStateColumns]
	SpellSlots  modAs[Q, spellSlotColumns]
	XPEvents    modAs[Q, xpEventColumns]
}

func (j characterJoins[Q]) aliasedAs(alias string) characterJoins[Q] {
	return buildCharacterJoins[Q](buildCharacterColumns(alias), j.typ)
}

func buildCharacterJoins[Q dialect.Joinable](cols characterColumns, typ string) characterJoins[Q] {
	return characterJoins[Q]{
		typ: typ,
		ActiveBuffs: modAs[Q, activeBuffColumns]{
			c: ActiveBuffs.Columns,
			f: func(to activeBuffColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ActiveBuffs.NameExpr().As(to.Alias())).On(
						to.CharacterID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		HPEvents: modAs[Q, hpEventColumns]{
			c: HPEvents.Columns,
			f: func(to hpEventColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, HPEvents.NameExpr().As(to.Alias())).On(
						to.CharacterID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RoundStates: modAs[Q, roundStateColumns]{
			c: RoundStates.Columns,
			f: func(to roundStateColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RoundStates.NameExpr().As(to.Alias())).On(
						to.CharacterID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		SpellSlots: modAs[Q, spellSlotColumns]{
			c: SpellSlots.Columns,
			f: func(to spellSlotColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SpellSlots.NameExpr().As(to.Alias())).On(
						to.CharacterID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		XPEvents: modAs[Q, xpEventColumns]{
			c: XPEvents.Columns,
			f: func(to xpEventColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, XPEvents.NameExpr().As(to.Alias())).On(
						to.CharacterID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
